    update_banner_text: "A new version of PaperGames is available.",
    update_banner_new_games: "New since your last visit: {s}.",
    update_banner_more_games: "{n} more",
    update_banner_list_sep: ", ",
    update_banner_more_notes: "And more improvements.",
    release_v223: "Saving for offline use is more robust, games are grouped into families, Domino has the variant “Triangles”, and “Who Took the Cake?” has the theme “Cats and fish” and gives more hints.",
    release_v224: "Card Duel: four decks of equal strength, against the computer or with two players on one device.",
    release_v225: "Fairy-Tale Villains: six villains from the Grimms' tales with goals of their own, for 2 to 4 players.",
    release_v226: "Forest Village: forest animals build a village through the seasons, for 1 to 4 players.",
    release_v227: "Adventure Book: a role-playing game for one – create a hero and explore a cave, a tower or a forest.",
    release_v228: "A small link in the footer of the home page leads to Quillwild, a new project in progress.",
    release_v229: "The home page is shorter now; the categories have pages of their own.",
    release_v230: "Card Duel: every card has a picture now.",
    release_v234: "Tangram has a new level, Outline only, with 29 new figures.",
    release_v235: "Picture search with nine rooms and over 40 new drawings; Who Took the Cake? with a family and with children and a treasure.",
    release_v236: "Picture search with bathroom, cellar and bedroom; Who Took the Cake? with five more rooms and seven new pieces of furniture.",
    release_v237: "New Games now shows the 10 newest games.",
    release_v241: "Forest Village has new rules, a renamed game, and revised descriptions; old Forest Village saves are discarded.",
    release_v242: "The game has a new name and address; old addresses now redirect.",
    release_v243: "Offline storage reloads less; Arabic spacing is fixed, active buttons are black, Shuffle asks first, and rules pages have a back link at the top.",
    release_v244: "Games open ready to play; the result window offers Play again; New game stays next to the board; Chess has its own two-player button.",
    release_v245: "Game pages have a one-row header and no site navigation; Settings moved into the menu; the control panel closes after the start, so more boards fit on the screen.",
    release_v246: "Game cards on all category pages are big tap targets; the kids page shows every kids game on one page with large icons; Large board makes tiny boards easier to tap; Cake is no longer listed as a kids game.",
    release_v249: "Pages load faster because they need less data. New games: Kleeberg and Pasture Friends.",
    release_v250: "In Steckwürfeln you can tap the holes, Klappenkasten shows what the computer closed, and Bingo allows up to four computer opponents. Durak and Skat buttons work again.",
    release_v251: "New game: Zoo Toss. Pasture Friends now explains itself with pictures, Schwimmen shows the right player's turn, the Kleeberg board is no longer cut off, and link previews show no game count.",
    release_v253: "Zoo Toss: you now put the paws on the card yourself, and after the computer's turn you see its card, dice and paws and tap Next.",
    release_v254: "The license changed: PaperGames may now be used for noncommercial purposes only (PolyForm Noncommercial 1.0.0). Nothing changes for playing.",
    release_v255: "Forest Village: the game description and the rules now name clay, seeds and feathers and the Clearing everywhere.",
    release_v256: "Offline: when the internet drops during an update, the old version now stays complete and keeps working, and the home page says in plain words what is missing and what to do.",
    release_v257: "Home page title and description now name Kindle, Kobo, Tolino and Boox (search results and link previews).",
    release_v258: "On a browser that is too old for PaperGames (for example the older Kindle browser), every page now shows a short note instead of a broken or blank page.",
    release_v259: "Sudoku and Killer Sudoku start and make new puzzles faster on slow e-readers, and pages no longer show English text for a moment before your language.",
    release_v260: "Every game now has a link “Report an idea or bug” at the bottom that opens your email program with game, version and language filled in. In Rummy the note on swapping a joker now names the house rule.",
    release_v261: "Rummy: a joker that fits at both ends of a run now goes where you choose, and there are two new options - Hand-Rommé (lay out all cards at once, the others' penalty points count double) and knocking on a discarded card against two or three computers.",
    release_v264: "Ludo: a board for 6 players. Blocked Path: a quick board with rest fields, and up to 6 players. Hex: Black and White with a clear colour choice. Picture help for Link the Pairs, Old Maid and Snakes and Ladders. Licence notes, privacy policy and three history pages updated.",
    release_v265: "Blocked Path: choose few, normal or many blocks. Small buttons are now big enough to tap, and three more games have a large board. Picture help for War and Pairs. Sternjagd names who starts. Ludo texts and 15 history pages checked and corrected.",
    release_v266: "Sternjagd: with 2 players the second player has two turns in a row the first time; you can switch this off. 15 more history pages checked and corrected.",
    release_v267: "Devilish Seven is now Lucky Chain, with its own rules: numbers 1 to 10, a bonus for numbers in a row, six new special cards and targets of 60, 90 or 120 points. A game saved under the old rules starts anew.",
    release_v263: "The dice race game with blocks on the paths has a new name: “Blocked Path”. Rules, saved games and statistics stay the same.",
    release_v262: "Minesweeper: the clock stays hidden unless you switch on “Show time”, and too many flags are named clearly. Hex: new swap rule (on by default). Domino: the stock button is always shown and big enough to tap. Chess: a note that the online mode needs internet and a Lichess account.",
    release_v252: "Bingo, Steckwürfeln, Klappenkasten, Zoo Toss and Pasture Friends now explain themselves with pictures, Zoo Toss has a beginner level, and the cake board names its rooms with numbers and has larger squares.",
    release_v248: "Seven new games (Bingo, three dice games and three children's puzzles), a new hardest level in Arrows, a hint button in Cat Places, better search and a Card Games page.",
    release_v247: "All games use the same names and status texts (Against the computer, Two players, one device, New game, Your turn); every game page has a Home button; Undo takes back your move and the computer's answer in 32 games.",
    release_v240: "Game names have changed in all 12 languages.",
    release_v239: "Removed protected game names from rules and history page descriptions.",
    release_v238: "Quick rules now match the selected cake theme and picture search mode.",
    release_v233: "Arrows on Hard: gliding arrows, 11 × 11 squares, and a new Master level with three hearts.",
    release_v232: "Move suggestions can be switched off in the Settings, and “Who Took the Cake?” has three new themes.",
    release_v231: "Spot the Difference has a new mode: picture search.",
