    game_blockers: "Blocked Path",
    home_blockers_desc: "A dice race to the goal at the top of the board for 2 to 6 players: blocks close the paths, and whoever lands on one puts it in the others' way. Against the computer or with friends on one device.",
    bl_level_label: "Level",
    bl_board_aria: "Blocked Path board",
    bl_history_intro: "Blocked Path is a race game at PaperGames; it takes up old elements of dice race games such as sending tokens home and blocking the way.",
    quickrules_blockers_1: "Roll and move one token exactly that many fields along the paths towards the goal at the top.",
    quickrules_blockers_2: "No token may pass over a block. Land on a block, and you put it on another free field - in someone else's way. Before the game you choose few, normal or many blocks.",
    quickrules_blockers_3: "In the upper half (round fields), landing on another player's token sends it back to its house; on the square fields below, tokens are safe. The first token in the goal wins - or, if chosen before the game, the first player with all tokens in the goal.",
    quickrules_blockers_4: "Quick board (chosen before the game): smaller, 4 tokens each; on a rest field (octagon) a token is safe, only one token fits, and no block may go there.",
