    game_blackjack: "Blackjack",
    home_blackjack_desc: "The card game of 21 against the bank: take cards or stand, but do not go over 21. Two variants: 17 and 4 with 32 cards and Blackjack with 52. Played with chips, which are only points in the game.",
    bj_variant_label: "Variant",
