    game_schafkopf: "Schafkopf",
    home_schafkopf_desc: "The Bavarian card game for four with German cards: you against three computers in Sauspiel, Wenz and Solo, with Schneider, Schwarz, Laufende and a points list. Points only, no money.",
    sf_history_intro: "Schafkopf is first mentioned in 1782 in Saxony; the first game clearly from Bavaria is recorded for 1849.",
    quickrules_schafkopf_1: "Pass or announce a game: Sauspiel (you call a Sow, its holder is your partner), Wenz or Solo.",
    quickrules_schafkopf_2: "Obers and Unters are the high trumps (in the Wenz only the Unters); follow suit. The called Sow must be played when its suit is led.",
    quickrules_schafkopf_3: "The playing side needs 61 of the 120 points. Schneider, Schwarz and Laufende raise the score.",
