    home_bridge_desc: "Contract bridge for four: you and your computer partner against two computers. Guided bidding with buttons, the dummy open on the table, scoring as Chicago (four deals) or rubber.",
    br_history_intro: "Bridge comes from whist; the first known rules (\"Biritch, or Russian Whist\") date from 1886, contract bridge from 1925.",
