    game_mathcross: "Calculation Grid",
    home_mathcross_desc: "Place the numbers 1 to 9 once each so every row and every column works out, worked from left to right. Three levels, always exactly one solution, solvable without guessing.",
    mc_history_intro: "A number puzzle of calculations in rows and columns, related to the ancient magic square of the numbers 1 to 9.",
    quickrules_mathcross_1: "Put the numbers 1 to 9 into the squares, each exactly once.",
    quickrules_mathcross_2: "Every row and every column must give its result. Work from left to right (top to bottom) - not times before plus: 3 + 4 × 2 = 14.",
    quickrules_mathcross_3: "Tap a square, then a number. A tick or cross shows whether a full row or column works out.",
    game_cardduel: "Card Duel",
    home_cardduel_desc: "A fantasy card game for two mages: creatures and spells, four ready-made decks of forest, fire, water and stone. Against the computer in three levels or with two players on one device.",
