    ab_room_cave_1: "Water drips from the ceiling into a small, clear pool.",
    ab_room_cave_2: "Blue crystals grow out of the walls and glow softly.",
    ab_room_cave_3: "A narrow passage. You have to duck under a low rock.",
    ab_room_cave_4: "Old mining carts stand on rusty rails. Someone worked here long ago.",
    ab_room_cave_5: "The cave opens into a high hall. Your steps echo.",
    ab_room_cave_6: "Glittering sand covers the floor. It crunches under your boots.",
    ab_room_cave_7: "A cold wind blows from a crack in the rock.",
    ab_room_cave_8: "Mushrooms as big as chairs grow here. They smell of earth.",
    ab_room_cave_9: "An underground stream rushes past in a stone channel.",
    ab_room_cave_10: "Strange drawings of stars cover one wall.",
    ab_room_cave_11: "Stalactites hang from the ceiling like icicles of stone.",
    ab_room_cave_12: "A small side cave. Someone left an old blanket here.",
    ab_room_cave_13: "The path climbs over smooth rocks, slippery with moss.",
    ab_room_cave_14: "Bats sleep in a dark corner. You walk on tiptoe.",
    ab_room_cave_15: "A round chamber with a smooth floor, as if polished.",
    ab_room_cave_16: "Green moss lights up the walls with a pale shine.",
    ab_room_cave_17: "A rope bridge once crossed here. Only the posts are left.",
    ab_room_cave_18: "The air is warm here. Somewhere deep below, something rumbles.",
    ab_room_cave_19: "Shards of crystal lie everywhere, as if a great stone had burst.",
    ab_room_cave_20: "A quiet nook. Your lamp throws long shadows.",
    ab_room_tower_1: "Shelves full of dusty books reach up to the ceiling.",
    ab_room_tower_2: "A spiral staircase winds upwards. The steps creak.",
    ab_room_tower_3: "Ravens sit on a beam and watch you with shiny eyes.",
    ab_room_tower_4: "An old kitchen. A kettle hangs over a cold fireplace.",
    ab_room_tower_5: "Through a round window you see the forest far below.",
    ab_room_tower_6: "A study with a huge desk. Ink has dried in the pots.",
    ab_room_tower_7: "Gears turn slowly behind a glass wall. Tick, tock.",
    ab_room_tower_8: "A long corridor with portraits. Their eyes seem to follow you.",
    ab_room_tower_9: "A room full of maps. One of them shows a tower like this one.",
    ab_room_tower_10: "Candles burn on a table, though nobody seems to be here.",
    ab_room_tower_11: "A storeroom with jars of dried herbs and coloured powders.",
    ab_room_tower_12: "Wind whistles through a broken shutter.",
    ab_room_tower_13: "A music room. A harp plays a note all by itself.",
    ab_room_tower_14: "A narrow bridge of planks leads from one wall to the other.",
    ab_room_tower_15: "A bedroom with a canopy bed. The curtains are full of holes.",
    ab_room_tower_16: "A workshop with a telescope pointing at the sky.",
    ab_room_tower_17: "Black feathers lie all over the floor.",
    ab_room_tower_18: "A mirror hangs on the wall, but it shows another room.",
    ab_room_tower_19: "A small balcony. Up here the wind smells of rain.",
    ab_room_tower_20: "A cold hall with a chessboard floor of black and white tiles.",
    ab_room_forest_1: "Mist hangs between the trees. You can hardly see your hand.",
    ab_room_forest_2: "A clearing full of flowers. Bees hum in the sun.",
    ab_room_forest_3: "An old path, overgrown with ferns.",
    ab_room_forest_4: "A hollow tree, big enough to stand inside.",
    ab_room_forest_5: "A small pond. Frogs jump into the water as you come.",
    ab_room_forest_6: "Roots as thick as arms cross the path.",
    ab_room_forest_7: "Birds sing high up in the treetops.",
    ab_room_forest_8: "A ring of white stones lies in the grass.",
    ab_room_forest_9: "Blackberry bushes grow along a stone wall.",
    ab_room_forest_10: "The ground is soft and green with moss. It is very quiet.",
    ab_room_forest_11: "A fallen trunk lies across a gully, like a bridge.",
    ab_room_forest_12: "An abandoned hut. The door hangs open.",
    ab_room_forest_13: "Tall pines creak in the wind.",
    ab_room_forest_14: "Tiny lights dance over a marsh.",
    ab_room_forest_15: "A huge oak with a face carved into its bark.",
    ab_room_forest_16: "Mushrooms grow in a perfect circle.",
    ab_room_forest_17: "A brook babbles over smooth pebbles.",
    ab_room_forest_18: "A dark thicket. Branches scratch at your sleeves.",
    ab_room_forest_19: "A sunny hill. From here you see the mist below like a sea.",
    ab_room_forest_20: "Old stone steps lead between two birch trees.",
    home_adventurebook_desc: "A role-playing game for one: create a hero, explore a cave, a tower or a forest room by room, roll dice for checks and fights and bring back a lost treasure. Easy, Medium or Hard.",
    quickrules_adventurebook_1: "Create a hero, then find the treasure of the place and bring it back to the entrance.",
    quickrules_adventurebook_2: "Checks: two dice plus a value must reach the number shown. The result is shown with the sum.",
    quickrules_adventurebook_3: "Fights go in rounds: attack, defend, use an item, your class ability or flee. The game saves after every step.",
