    game_pentomino: "Pentomino Puzzle",
    home_pentomino_desc: "Lay the twelve pieces of five squares into a rectangle - turn and flip them with a tap, no dragging. Free laying in four field sizes, or with start pieces given and exactly one solution.",
    pt_history_intro: "Twelve pieces of five squares each: a puzzle published by Henry Dudeney in 1907, named \"pentominoes\" by Solomon Golomb in 1953.",
    quickrules_pentomino_1: "Fill the rectangle with the pieces; every square is covered exactly once.",
    quickrules_pentomino_2: "Choose a piece below the board, turn or flip it, then tap the square where its dot should go. Tap a laid piece to pick it up again.",
    quickrules_pentomino_3: "With \"Start pieces given\" some pieces lie fixed and the rest fit in exactly one way.",
    pt_mode_label: "Mode:",
    pt_mode_free: "Free laying",
    pt_mode_fixed: "Start pieces given",
