    msg_pt_place: "Turn or flip it if needed, then tap where its dot should go.",
    msg_pt_nofit: "The piece does not fit there.",
    msg_pt_fixed: "That piece is fixed.",
    msg_t_pt_picked: "Piece {s} picked up.",
    msg_pt_won: "The rectangle is full - solved!",
    msg_t_pt_hint_place: "Hint: piece {s} goes in the marked place.",
    msg_t_pt_hint_remove: "Hint: piece {s} blocks the solution - take it off.",
    msg_pt_hint_none: "Hint: no way found - take off a piece.",
    msg_t_pt_info: "Pieces laid: {n} of {m}",
    game_arrows: "Arrows",
    home_arrows_desc: "Tap an arrow and it slides out of the field - if no other arrow is in its way. Clear the whole field; every puzzle can be solved, with undo and hints and no time limit. On Hard and Master, blocked arrows glide forward and can get stuck.",
    aw_history_intro: "Pieces that may slide only one way are relatives of the sliding puzzles that became a craze in 1880; the version with arrows is a young puzzle.",
    quickrules_arrows_1: "Tap an arrow: it leaves the field in the direction it points if the way to the edge is free.",
    quickrules_arrows_2: "If another arrow is in the way, nothing happens - take that one out first. On Hard and Master it glides forward up to that arrow instead.",
    quickrules_arrows_3: "Clear the whole field. Every puzzle can be solved; Hint marks an arrow that can leave.",
    aw_win_title: "Field cleared!",
    aw_aria_cell: "Row {R}, column {C}",
    aw_aria_empty: "empty",
    aw_aria_arrow: "arrow pointing {D}",
    aw_dir_0: "up",
    aw_dir_1: "right",
    aw_dir_2: "down",
    aw_dir_3: "left",
    msg_aw_start: "Tap an arrow to send it out of the field.",
    tg_level_outline: "Outline only",
    game_loosen: "Loosen the Rings",
    home_loosen_desc: "Rings hooked into each other, each with a gap: turn them - hooked rings turn along the other way - until one after the other slips off. Three levels, with the fewest moves, undo and hints.",
    lr_history_intro: "Ring puzzles are old - the Chinese rings were described around 1500; this flat version with gaps is new.",
    quickrules_loosen_1: "Tap a ring: it turns a quarter clockwise, and the rings hooked into it turn the other way.",
    quickrules_loosen_2: "A ring is free when its gap sits where the hooked ring lies on top - tap it and it comes out.",
    quickrules_loosen_3: "Take out all the rings; the rings at the ends go first. Hint shows a move.",
    lr_win_title: "All loose!",
    lr_aria_ring: "Ring {N}, gap {D}",
