    game_zoowurf: "Zoo Toss",
    home_zoowurf_desc: "A dice game for children: roll the animal dice and fill the card with the animals it shows - lion, elephant, giraffe, monkey and penguin. Pictures only, no reading needed, no time limit. Against the computer or with up to four players on one device.",
    zoowurf_history_intro: "Rolling dice and matching pictures are among the first games small children play - this one combines both with a set of zoo animals.",
    quickrules_zoowurf_1: "Tap one of the two open cards. It shows the animals you must roll.",
    quickrules_zoowurf_2: "Roll the dice up to three times. Dice with an animal of the card, or the paw, stay on the card. Roll the rest again.",
    quickrules_zoowurf_3: "Full card: you win it, and a new round starts. Not full: the next player continues. Whoever has four cards first wins.",
    game_tieryatzy: "Animal Yatzy",
    home_tieryatzy_desc: "A dice game for children with animal dice: roll up to three times, keep the animals you want and fill your sheet - lions, elephants, two or more the same, all different. The paw is a joker. Pictures only, no sums. Alone, against the computer or with up to four players on one device.",
    tieryatzy_history_intro: "Rolling five dice up to three times and choosing where to score is an old dice game idea - here with animals instead of numbers.",
    quickrules_tieryatzy_1: "Roll the five animal dice. Tap the dice you want to keep and roll the others again - up to three times.",
    quickrules_tieryatzy_2: "Then tap one free field of your sheet. The paw counts as any animal. A field that does not fit gets 0 points.",
    quickrules_tieryatzy_3: "When every field is full, the game ends. Whoever has the most points wins.",
    ty_mode_people: "People on one device",
