    game_slidepuzzle: "Sliding Puzzle",
    home_slidepuzzle_desc: "Slide the numbered tiles into order with the gap at the bottom right. Every puzzle can be solved; 3 × 3, 4 × 4 or 5 × 5, with hints and no timer.",
    slidepuzzle_history_intro: "A box of numbered tiles and one empty place: in 1880 the sliding puzzle was a craze in the United States.",
    quickrules_slidepuzzle_1: "Tap a tile in the same row or column as the gap: it slides into the gap, and so do the tiles in between.",
    quickrules_slidepuzzle_2: "Put the numbers in order, row by row, with the gap at the bottom right.",
    quickrules_slidepuzzle_3: "Every puzzle can be solved. Stuck? The Hint button marks a tile to move.",
