    game_hanoi: "Tower of Hanoi",
    home_hanoi_desc: "Move the whole tower of discs to the right rod, one disc at a time, never a bigger disc on a smaller one. 3 to 8 discs, move counter, undo and hints.",
    hanoi_history_intro: "A puzzle from 1883 that came with an invented legend - and a neat rule for the fewest moves.",
    quickrules_hanoi_1: "Tap a rod to pick up its top disc, then tap the rod to put it on.",
    quickrules_hanoi_2: "A disc may never lie on a smaller one.",
    quickrules_hanoi_3: "Move the whole tower to the right rod (with the star). The fewest moves: 2 to the power of the number of discs, minus 1.",
