    game_nim: "Nim",
    home_nim_desc: "Take stones from the heaps in turn - whoever takes the last stone wins (or, in misère, loses). Against the computer at three levels or with two players.",
    nim_history_intro: "A game of taking stones that Charles L. Bouton named and solved in 1901.",
    quickrules_nim_1: "On your turn take one or more stones from one row: tap the stone up to which you want to take, then \"Take stones\".",
    quickrules_nim_2: "Normal: whoever takes the last stone wins. Misère: whoever takes the last stone loses.",
    quickrules_nim_3: "The line under the heaps says whether the start is won or lost for whoever begins. From a winning position the Hard computer cannot be beaten.",
