    sw_again_hint: "Double six! Roll again.",
    game_steckwuerfeln: "Steckwürfeln",
    home_steckwuerfeln_desc: "A traditional peg-and-dice game with eleven holes numbered 2 to 12: roll two dice and peg the hole of the total, or the two holes of the single dice. Keep rolling until nothing fits - the free holes count against you, the fewest points win. Variants: double six as a joker, or one shared board where whoever cannot peg is out.",
    sw_history_intro: "A small traditional dice game on a board with numbered holes and pegs - simple, old and still sold as a wooden pocket game.",
    quickrules_steckwuerfeln_1: "Roll two dice. Peg the hole of the total, or the two holes of the single dice (2 and 4: hole 6, or holes 2 and 4).",
    quickrules_steckwuerfeln_2: "Keep rolling and pegging. When nothing fits, the numbers of the free holes are your points.",
    quickrules_steckwuerfeln_3: "The fewest points win. Double six is a joker (roll again). Undo takes back a peg.",
    sw_goal_line: "Goal: put pegs into the holes. The holes left free count as points - the fewest points win.",
