    game_teufelsieben: "Lucky Chain",
    home_teufelsieben_desc: "A push-your-luck card game: reveal cards one by one, then stop in time. Repeating a number makes you bust; runs of four or more numbers earn a bonus. 2 to 6 players, against the computer or on one device.",
    quickrules_teufelsieben_1: "On your turn, reveal cards one by one. After the first card, you may stop at any time.",
