    game_gipfelwurf: "Ridge Roll",
    home_gipfelwurf_desc: "A push-your-luck dice game: roll four dice, pair them up and climb seven ridges. Roll on or stop and make camp - if no pair fits, the climbing of the turn is lost. Reach the top of three ridges first. 2 to 4 players, against the computer or on one device.",
    quickrules_gipfelwurf_1: "Roll four dice and choose two pairs: each pair sum moves your climber one step up its ridge. At most three climbers per turn.",
    quickrules_gipfelwurf_2: "Roll on or stop: stopping turns the climbers into camps. If no pair fits, the climbing of this turn is lost.",
    quickrules_gipfelwurf_3: "A camp at the top claims the ridge for you. Whoever claims three ridges first (or two, as chosen) wins.",
    gw_history_intro: "Roll on or make camp? Ridge Roll is a push-your-luck dice game made for PaperGames, in the old family of dice games in which one more roll can cost everything.",
