    game_advent: "Puzzle Advent Calendar",
    home_advent_desc: "24 doors, one small puzzle behind each: Light Switch, mini Sudoku, picture logic, Futoshiki, Skyscrapers and Calcudoku. A door opens on its day in December once the one before is solved.",
    quickrules_advent_1: "From 1 to 24 December one door opens each day. Behind it is a small puzzle that takes a few minutes.",
    quickrules_advent_2: "A door opens only when the door before it is solved. Missed a day? Solve the earlier doors and the later ones follow.",
    quickrules_advent_3: "Tap a cell, then a number below. In a picture puzzle a cell turns filled, then crossed, then empty again.",
    adv_history_intro: "Counting the days to Christmas: from chalk lines on a door to printed calendars with small doors - and here one small puzzle a day.",
