    adv_text_1: "The first door is open - 23 more to come.",
    adv_text_2: "Outside it is getting dark early; a puzzle fits the long evenings.",
    adv_text_3: "A cup of tea and a picture made of squares - a good start to the day.",
    adv_text_4: "Little by little the days are counted down.",
    adv_text_5: "Outside the first frost may come; inside the numbers fall into place.",
    adv_text_6: "Almost a week of December is behind you.",
    adv_text_7: "One week of puzzles done - well kept up.",
    adv_text_8: "Lists, letters, little plans: December is full - and this door is done.",
    adv_text_9: "Somewhere the first snowflakes are falling right now.",
    adv_text_10: "Ten doors open - the calendar is filling up.",
    adv_text_11: "Short days, long nights: good time for thinking.",
    adv_text_12: "Half the calendar is almost behind you.",
    adv_text_13: "A warm drink, a quiet minute, a solved puzzle.",
    adv_text_14: "Two weeks of December - the countdown is in full swing.",
    adv_text_15: "Somewhere biscuits are being baked; here a puzzle is solved.",
    adv_text_16: "Only eight more doors to go.",
    adv_text_17: "Bright windows in the dark street - and one more door open.",
    adv_text_18: "Wrapping paper, ribbons and one more solved puzzle.",
    adv_text_19: "The year is nearly over; the puzzles keep you going.",
    adv_text_20: "Twenty doors - only four to go.",
    adv_text_21: "Only three doors left - the calendar is nearly full.",
    adv_text_22: "Almost there: a few more doors and the calendar is complete.",
    adv_text_23: "The day before the last door - well done for coming this far.",
    adv_text_24: "All 24 doors are open. Happy holidays and a peaceful time!",
