    game_catplaces: "Cat Places",
    home_catplaces_desc: "Every row, every column and every room gets exactly one cat - and no two cats may touch, not even at a corner. Logic puzzles in three sizes, each with exactly one solution, solvable without guessing.",
    kz_history_intro: "The rules come from a logic puzzle devised in 2003 for the World Puzzle Championship in the Netherlands; here sleeping cats take the place of stars.",
    quickrules_catplaces_1: "Place one cat in every row, every column and every room (the areas inside the thick lines).",
    quickrules_catplaces_2: "Two cats may never touch - not side by side and not at a corner.",
    quickrules_catplaces_3: "Tap a cell once for a cat, again for a dot (no cat here), a third time to clear it. Hint shows a cell.",
