    game_rings: "Turn the Rings",
    home_rings_desc: "Three to five rings, one inside the other, with shapes on them. Turn the rings until every ray from the middle shows the same shape - on Hard a ring turns its neighbour along. Fewest moves shown, with a hint button.",
    rg_history_intro: "Rings with signs that are turned against each other are old: Leon Battista Alberti described a cipher disk of two turning rings in 1467. The puzzle here is made for PaperGames.",
    quickrules_rings_1: "Turn a ring left ↺ or right ↻ with the buttons under the picture.",
    quickrules_rings_2: "Goal: every one of the 8 rays from the middle shows the same shape on every ring.",
    quickrules_rings_3: "On Hard a ring turns the next ring outwards along. Hint shows a good turn; the fewest moves are shown.",
