    game_matches: "Matchstick Puzzles",
    home_matches_desc: "Move one or two matches so that a wrong sum becomes right, or so that the figure shows a given number of squares. 90 puzzles in three levels, each checked by computer; tap a match, then a free place - no dragging.",
    mt_history_intro: "Matches became an everyday thing in the 19th century and soon a puzzle material: Professor Hoffmann's book Puzzles Old and New (1893) already has a chapter of puzzles with matches.",
    quickrules_matches_1: "Tap a match to pick it up, then tap a free place to lay it there.",
    quickrules_matches_2: "Move exactly as many matches as the task says: 1 or 2.",
    quickrules_matches_3: "Make the sum right, or make the asked number of squares. Undo, Start over and Hint help.",
